def find_max_number(binary_str: str) -> str:
    max_index = get_max_digit_index(binary_str)
    return binary_str[:max_index] + binary_str[max_index + 1:]

def get_max_digit_index(binary_str: str) -> int:
    max_digit = -1
    max_index = -1
    current_max = 0
    for i, digit in enumerate(binary_str):
        if int(digit) > current_max:
            current_max = int(digit)
            max_digit = current_max
            max_index = i
    return max_index
